def count_good_puzzles(A, B, picture):
    good_puzzles = set()
    min_area = A * B

    for x in range(1, A + 1):
        if A % x == 0:
            for y in range(1, B + 1):
                if B % y == 0:
                    pieces = []
                    for i in range(0, A, x):
                        for j in range(0, B, y):
                            piece = [row[j:j+y] for row in picture[i:i+x]]
                            pieces.append(''.join(piece))
                    if len(set(pieces)) == len(pieces):
                        good_puzzles.add((x, y))
                        area = x * y
                        if area < min_area:
                            min_area = area

    return len(good_puzzles), min(good_puzzles, key=lambda p: (p[0] * p[1], p[0]))

